"use client";

import { motion, type HTMLMotionProps } from "motion/react";
import { cn } from "@/lib/cn";
import type { ReactNode } from "react";

interface CardProps extends HTMLMotionProps<"div"> {
  children: ReactNode;
  interactive?: boolean;
}

export function Card({
  className,
  children,
  interactive = false,
  ...rest
}: CardProps) {
  return (
    <motion.div
      whileHover={interactive ? { y: -4 } : undefined}
      transition={{ type: "spring", stiffness: 260, damping: 22 }}
      className={cn(
        "relative rounded-[var(--radius-lg)] bg-white",
        "shadow-[0_1px_2px_rgb(0_0_0/0.04),0_1px_3px_rgb(0_0_0/0.03)]",
        "ring-1 ring-neutral-200/70",
        interactive &&
          "transition-shadow duration-300 hover:ring-neutral-300/80 hover:shadow-[0_18px_36px_-16px_rgb(0_0_0/0.14),0_4px_10px_-4px_rgb(0_0_0/0.06)]",
        className,
      )}
      {...rest}
    >
      {children}
    </motion.div>
  );
}
