function EditorPane() {
  const lines = [
    { n: 1, tokens: [{ t: "int ", c: "text-neutral-500" }, { t: "twoSum", c: "text-neutral-950" }, { t: "(vector<int>& nums, ", c: "text-neutral-600" }, { t: "int ", c: "text-neutral-500" }, { t: "target) {", c: "text-neutral-600" }] },
    { n: 2, tokens: [{ t: "  unordered_map<", c: "text-neutral-600" }, { t: "int", c: "text-neutral-500" }, { t: ", ", c: "text-neutral-600" }, { t: "int", c: "text-neutral-500" }, { t: "> seen;", c: "text-neutral-600" }] },
    { n: 3, tokens: [{ t: "  for (", c: "text-neutral-600" }, { t: "int ", c: "text-neutral-500" }, { t: "i = 0; i < nums.size(); i++) {", c: "text-neutral-600" }] },
    { n: 4, tokens: [{ t: "    ", c: "text-neutral-600" }, { t: "int ", c: "text-neutral-500" }, { t: "need = target - nums[i];", c: "text-neutral-600" }] },
    { n: 5, tokens: [{ t: "    if (seen.count(need)) return {seen[need], i};", c: "text-neutral-600" }] },
    { n: 6, tokens: [{ t: "    seen[nums[i]] = i;", c: "text-neutral-600" }] },
    { n: 7, tokens: [{ t: "  }", c: "text-neutral-600" }] },
    { n: 8, tokens: [{ t: "  return {};", c: "text-neutral-600" }] },
    { n: 9, tokens: [{ t: "}", c: "text-neutral-600" }] },
  ];

  return (
    <main className="col-span-7 p-4 lg:col-span-8">
      <div className="mb-2 flex items-center justify-between">
        <div className="flex items-center gap-1.5 text-[11px] text-neutral-500">
          <div className="h-1.5 w-1.5 rounded-full bg-neutral-950" />
          solution.cpp
        </div>
        <div className="flex items-center gap-2">
          <button className="h-7 rounded-full bg-white px-2.5 text-[11px] font-medium ring-1 ring-neutral-200">
            C++
          </button>
          <button className="inline-flex h-7 items-center gap-1 rounded-full bg-neutral-950 px-2.5 text-[11px] font-medium text-white">
            <Play className="h-3 w-3" /> Run
          </button>
        </div>
      </div>

      <div className="rounded-xl bg-neutral-950 p-4 font-mono text-[12px] leading-relaxed text-neutral-300">
        {lines.map((line) => (
          <motion.div
            key={line.n}
            initial={{ opacity: 0, x: -6 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.8 + line.n * 0.05, duration: 0.5 }}
            className="flex gap-4"
          >
            <span className="w-4 text-right text-neutral-600">{line.n}</span>
            <span>
              {line.tokens.map((tok, i) => (
                <span key={i} className={tok.c.replace("text-neutral-", "text-neutral-")}>
                  {tok.t}
                </span>
              ))}
            </span>
          </motion.div>
        ))}
      </div>

      <div className="mt-4 grid grid-cols-3 gap-2">
        {[
          { label: "Case 1", state: "passed" as const },
          { label: "Case 2", state: "passed" as const },
          { label: "Case 3", state: "running" as const },
        ].map((c, i) => (
          <motion.div
            key={c.label}
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1.4 + i * 0.06 }}
            className="flex items-center gap-2 rounded-lg bg-white p-2.5 text-[11.5px] ring-1 ring-neutral-200/70"
          >
            {c.state === "passed" ? (
              <span className="grid h-5 w-5 place-items-center rounded-full bg-neutral-950 text-white">
                <Check className="h-3 w-3" />
              </span>
            ) : (
              <span className="grid h-5 w-5 place-items-center rounded-full bg-white ring-1 ring-neutral-300">
                <span className="h-1.5 w-1.5 rounded-full bg-neutral-950 animate-pulse" />
              </span>
            )}
            <div>
              <div className="font-medium">{c.label}</div>
              <div className="text-[10.5px] text-neutral-500">
                {c.state === "passed" ? "12ms · passed" : "running…"}
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </main>
  );
}

